<?php $v = fn($k) => e(App\Core\Session::old($k, (string) ($x[$k] ?? ''))); $sel = fn($k, $id) => (string) App\Core\Session::old($k, (string) ($x[$k] ?? '')) === (string) $id ? 'selected' : ''; ?>
<div class="card" style="max-width:860px"><div class="card-body">
