  <div class="col-md-4"><label class="form-label">Boutique</label><select name="store_id" class="form-select"><option value="">—</option><?php foreach ($stores as $s): ?><option value="<?= (int) $s['id'] ?>" <?= $sel('store_id', $s['id']) ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-4"><label class="form-label">Caisse affectée</label><select name="register_id" class="form-select"><option value="">— (pas de vente)</option><?php foreach ($registers as $r): ?><option value="<?= (int) $r['id'] ?>" <?= $sel('register_id', $r['id']) ?>><?= e($r['store'] . ' / ' . $r['name']) ?></option><?php endforeach; ?></select></div>
  <div class="col-md-6"><label class="form-label <?= empty($x['id']) ? 'required' : '' ?>">Mot de passe <?= !empty($x['id']) ? '(laisser vide pour conserver)' : 'provisoire' ?></label><input type="password" name="password" class="form-control" <?= empty($x['id']) ? 'required' : '' ?> minlength="<?= (int) config('app.security.password_min_length') ?>" autocomplete="new-password"><div class="form-text">L'utilisateur devra le changer à sa première connexion.</div></div>
  <?php if (setting('rfid_enabled') === '1'): ?><div class="col-md-6"><label class="form-label">Badge RFID</label><input type="password" name="badge" class="form-control" placeholder="Passer le badge sur le lecteur" autocomplete="off"><?php if (!empty($x['badge_hash'])): ?><div class="form-check"><input type="checkbox" class="form-check-input" name="remove_badge" value="1" id="rb"><label for="rb" class="form-check-label small">Retirer le badge actuel</label></div><?php endif; ?></div><?php endif; ?>
  <div class="col-12"><button class="btn btn-primary">Enregistrer</button> <a href="<?= e(url('/users')) ?>" class="btn btn-light">Annuler</a></div>
